import*as THREE from'three';import{Component,Port,materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{roundedRect}from'../../core/geometry.js';import{mesh,screw,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import data from'./geometry-data.js';import{addStickers}from'./stickers.js';
